import type { GearItem, WeightUnit } from '@/types/database'

// Type for gear items during parsing - GearItem without database metadata
export type ParsedGearItem = Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>

// CSV row type
export interface CsvRow {
  [key: string]: string
}

export interface ParseResult<T> {
  success: boolean
  data: T[]
  errors: string[]
  warnings: string[]
  metadata?: any
}

export type GearParseResult = ParseResult<ParsedGearItem>

// Common validation functions
export function validateParsedGearItem(item: ParsedGearItem): string[] {
  const errors: string[] = []

  if (!item.description || item.description.length < 2) {
    errors.push('Description must be at least 2 characters')
  }

  if (item.weight_g <= 0) {
    errors.push('Weight must be greater than 0')
  }

  if (item.weight_g > 50000) { // 50kg limit
    errors.push('Weight seems unrealistically high (over 50kg)')
  }

  if (!item.item_type || item.item_type.trim().length === 0) {
    errors.push('Item type is required')
  }

  if (item.price !== null && item.price !== undefined && item.price < 0) {
    errors.push('Price cannot be negative')
  }

  return errors
}

// Helper to convert ParsedGearItem to GearItem creation data
export function toGearItemData(item: ParsedGearItem): Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'> {
  return {
    description: item.description,
    item_type: item.item_type,
    brand: item.brand,
    model: item.model,
    consumable: item.consumable,
    price: item.price,
    weight_g: item.weight_g,
    weight_unit_display: item.weight_unit_display,
    notes: item.notes,
    image_url: item.image_url,
    url: item.url
  }
}

// Weight parsing utilities
export interface WeightParseResult {
  grams: number
  unit: WeightUnit
}

export function parseWeightFromText(text: string): WeightParseResult {
  const cleaned = text.toLowerCase().replace(/[^\d.,ozlbkg\s]/g, '').trim()

  // Handle combined lb + oz format (e.g., "1 lb 5 oz")
  if (cleaned.includes('lb') && cleaned.includes('oz')) {
    const lbOzMatch = cleaned.match(/(\d+\.?\d*)\s*lb\s*(\d+\.?\d*)\s*oz/)
    if (lbOzMatch) {
      const lbs = parseFloat(lbOzMatch[1])
      const ozs = parseFloat(lbOzMatch[2])
      const grams = Math.round((lbs * 453.592) + (ozs * 28.3495))
      return { grams, unit: 'oz' } // Display in oz since it has oz precision
    }
  }

  // Single unit parsing
  const patterns = [
    { regex: /(\d+\.?\d*)\s*oz/, unit: 'oz' as WeightUnit, factor: 28.3495 },
    { regex: /(\d+\.?\d*)\s*lb/, unit: 'lb' as WeightUnit, factor: 453.592 },
    { regex: /(\d+\.?\d*)\s*kg/, unit: 'kg' as WeightUnit, factor: 1000 },
    { regex: /(\d+\.?\d*)\s*g/, unit: 'g' as WeightUnit, factor: 1 },
  ]

  for (const pattern of patterns) {
    const match = cleaned.match(pattern.regex)
    if (match) {
      const value = parseFloat(match[1])
      const grams = Math.round(value * pattern.factor)
      return { grams, unit: pattern.unit }
    }
  }

  // Fallback: try to parse as plain number (assume grams)
  const numMatch = cleaned.match(/(\d+\.?\d*)/)
  if (numMatch) {
    const value = parseFloat(numMatch[1])
    return { grams: Math.round(value), unit: 'g' }
  }

  throw new Error(`Could not parse weight from: ${text}`)
}

// Boolean parsing utility
export function parseBoolean(value: string | undefined): boolean {
  if (!value) return false
  const lower = value.toLowerCase().trim()
  return ['true', 'yes', '1', 'on', 'checked', 'x'].includes(lower)
}

// Bulk validation function for arrays of items
export function validateGearItems(items: ParsedGearItem[]): { valid: ParsedGearItem[], invalid: { item: ParsedGearItem, errors: string[] }[] } {
  const valid: ParsedGearItem[] = []
  const invalid: { item: ParsedGearItem, errors: string[] }[] = []

  for (const item of items) {
    const errors = validateParsedGearItem(item)
    if (errors.length === 0) {
      valid.push(item)
    } else {
      invalid.push({ item, errors })
    }
  }

  return { valid, invalid }
}

// Duplicate checking function
export function checkForDuplicates(items: ParsedGearItem[]): { unique: ParsedGearItem[], duplicates: { item: ParsedGearItem, duplicateOf: number }[], warnings: string[] } {
  const unique: ParsedGearItem[] = []
  const duplicates: { item: ParsedGearItem, duplicateOf: number }[] = []

  for (let i = 0; i < items.length; i++) {
    const currentItem = items[i]
    let isDuplicate = false

    for (let j = 0; j < unique.length; j++) {
      const existingItem = unique[j]

      // Check if descriptions match (case-insensitive)
      const descriptionsMatch = currentItem.description.toLowerCase().trim() === existingItem.description.toLowerCase().trim()

      // Check if weights are similar (within 5g)
      const weightsMatch = Math.abs(currentItem.weight_g - existingItem.weight_g) <= 5

      // Check if brands match (case-insensitive, treating null/undefined as empty)
      const brandsMatch = (currentItem.brand || '').toLowerCase().trim() === (existingItem.brand || '').toLowerCase().trim()

      if (descriptionsMatch && weightsMatch && brandsMatch) {
        duplicates.push({ item: currentItem, duplicateOf: j })
        isDuplicate = true
        break
      }
    }

    if (!isDuplicate) {
      unique.push(currentItem)
    }
  }

  const warnings: string[] = []
  if (duplicates.length > 0) {
    warnings.push(`Found ${duplicates.length} potential duplicate${duplicates.length === 1 ? '' : 's'} (similar description/weight/brand)`)
  }

  return { unique, duplicates, warnings }
}

// Common column mapping type
export interface ColumnMap {
  [field: string]: number | undefined
}

import { decode as decodeHtmlEntities } from 'he'
import { 
  type ParsedGearItem, 
  type GearParseResult, 
  validateParsedGearItem 
} from './index'

export function parseLighterPackHtml(html: string): GearParseResult {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: [],
    metadata: {}
  }

  try {
    // Extract list name from title or h1
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i) || 
                      html.match(/<h1[^>]*>([^<]+)<\/h1>/i)

    if (titleMatch) {
      result.metadata.listName = titleMatch[1].replace(/\s*-\s*LighterPack.*$/i, '').trim()
    }

    // Look for all lpItem elements across all categories
    const itemMatches = html.match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>.*?<\/li>/gis)


    if (!itemMatches || itemMatches.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
      return result
    }

    // Parse each item
    for (const itemHtml of itemMatches) {
      try {
        const item = parseHtmlItem(itemHtml)
        if (item) {
          const validationErrors = validateParsedGearItem(item)
          if (validationErrors.length === 0) {
            result.data.push(item)
          } else {
            result.errors.push(`Invalid item: ${validationErrors.join(', ')}`)
          }
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.warnings.push(`Failed to parse item: ${message}`)
      }
    }

    // Calculate metadata
    if (result.data.length > 0) {
      result.metadata.totalWeight = result.data.reduce((sum, item) => sum + item.weight_g, 0)
      result.metadata.itemCount = result.data.length
    }

    result.success = result.data.length > 0

    if (result.data.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseHtmlItem(itemHtml: string): ParsedGearItem | null {
  try {
    // Extract name (item_type) from lpName span - handle both plain text and anchor tags
    const nameSpanMatch = itemHtml.match(/<span[^>]*class="[^"]*lpName[^"]*"[^>]*>(.*?)<\/span>/is)
    let name = null
    if (nameSpanMatch) {
      // Check if there's an anchor tag inside
      const anchorMatch = nameSpanMatch[1].match(/<a[^>]*>([^<]+)<\/a>/i)
      name = anchorMatch ? anchorMatch[1].trim() : nameSpanMatch[1].trim()
    }

    if (!name) {
      return null
    }

    // Extract description from lpDesc span, or anchor text within lpName
    let description = name // fallback to name

    // Try to get description from lpDescription
    const descMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDescription[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (descMatch?.[1]?.trim()) {
      description = descMatch[1].trim()
    } else {
      // Try to get from anchor text in lpName
      const anchorMatch = itemHtml.match(/<a[^>]*>([^<]+)<\/a>/i)
      if (anchorMatch?.[1]?.trim() && anchorMatch[1].trim() !== name) {
        description = anchorMatch[1].trim()
      }
    }

    // Extract URL from anchor in lpName
    const urlMatch = itemHtml.match(/<a[^>]*href="([^"]+)"/i)
    const url = urlMatch?.[1] ? decodeHtmlEntities(urlMatch[1]) : null

    // Extract weight and unit from lpWeight span and lpUnitSelect
    const weightMatch = itemHtml.match(/<span[^>]*class="[^"]*lpWeight[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (!weightMatch) return null

    const unitMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDisplay[^"]*"[^>]*>([^<]+)<\/span>/i)
    const unit = unitMatch?.[1]?.trim() || 'g'

    const weight = parseFloat(weightMatch[1])
    if (isNaN(weight)) return null

    // Convert to grams based on unit
    let weight_g: number
    switch (unit.toLowerCase()) {
      case 'oz':
        weight_g = Math.round(weight * 28.3495)
        break
      case 'lb':
        weight_g = Math.round(weight * 453.592)
        break
      case 'kg':
        weight_g = Math.round(weight * 1000)
        break
      case 'g':
      default:
        weight_g = Math.round(weight)
        break
    }

    const weight_unit_display = unit as 'g' | 'oz' | 'lb' | 'kg'


    // Check if item is consumable (must have an i element with both lpConsumable and lpActive classes)
    const consumable = /<i[^>]*class="[^"]*lpConsumable[^"]*lpActive[^"]*"[^>]*>|<i[^>]*class="[^"]*lpActive[^"]*lpConsumable[^"]*"[^>]*>/i.test(itemHtml)

    // Extract price from lpPriceCell span
    const priceMatch = itemHtml.match(/<span[^>]*class="[^"]*lpPriceCell[^"]*"[^>]*>\$?([0-9.,]+)<\/span>/i)
    const price = priceMatch ? parseFloat(priceMatch[1].replace(/[,$]/g, '')) : null

    // Use name directly as item_type (preserve original data)
    const item_type = name

    const result = {
      description: description || name, // Use description as the main field, fallback to name
      brand: null, // LighterPack doesn't separate brand info
      model: null,
      weight_g,
      weight_unit_display,
      item_type,
      consumable,
      price,
      notes: null, // LighterPack doesn't have separate notes
      image_url: null,
      url
    }

    return result

  } catch (error) {
    console.warn('Error parsing LighterPack item:', error)
    return null
  }
}

export async function parseLighterPackUrl(url: string): Promise<GearParseResult> {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: []
  }

  // Validate URL format
  if (!url.match(/^https:\/\/lighterpack\.com\/r\/[a-zA-Z0-9]+$/)) {
    result.errors.push('Invalid LighterPack URL format. Expected: https://lighterpack.com/r/[ID]')
    return result
  }

  // For now, direct URL import is not implemented
  result.errors.push('Direct URL import not yet implemented. Please use CSV export from LighterPack for now.')
  return result
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '@/contexts/AuthContext'
import { createGearRepository } from '@/lib/gearRepository'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { CheckCircle, AlertCircle, Info, Package, X, Weight, Tag, Loader2 } from 'lucide-react'
import { StatTile } from '@/components/ui/stat-tile'
import { GearTable } from '@/components/gear/GearTable'
import { formatWeightForDisplay } from '@/utils/weight'
import type { ParsedGearItem } from '@/utils/parser'
import type { GearItem } from '@/types/database'

interface ImportPreviewProps {
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors?: string[]
  warnings?: string[]
  metadata?: any
  onCancel: () => void
  className?: string
}

export function ImportPreview({
  newItems,
  duplicates,
  errors = [],
  metadata,
  onCancel,
  className
}: ImportPreviewProps) {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [isImporting, setIsImporting] = useState(false)
  const [importError, setImportError] = useState<string | null>(null)
  const newItemsWeight = newItems.reduce((sum, item) => sum + item.weight_g, 0)
  const newCategories = new Set(newItems.map(item => item.item_type))

  const handleImport = async () => {
    if (!user) {
      setImportError('User not authenticated')
      return
    }

    setIsImporting(true)
    setImportError(null)

    try {
      const gearRepository = createGearRepository(user.id)

      // Convert newItems to the format expected by the repository
      const itemsToCreate = newItems.map(item => ({
        item_type: item.item_type,
        description: item.description,
        brand: item.brand,
        model: item.model,
        consumable: item.consumable,
        price: item.price,
        weight_g: item.weight_g,
        weight_unit_display: item.weight_unit_display,
        notes: item.notes,
        image_url: item.image_url,
        url: item.url
      }))

      // Use createMany for bulk insert
      await gearRepository.createMany(itemsToCreate)

      // Redirect to gear closet
      navigate('/gear')
    } catch (error) {
      console.error('Failed to import items:', error)
      setImportError(error instanceof Error ? error.message : 'Unknown error occurred')
    } finally {
      setIsImporting(false)
    }
  }

  // Convert ParsedGearItem to GearItem format for GearTable - combine new items and duplicates
  const convertToGearItem = (item: ParsedGearItem, index: number, isDuplicate: boolean = false): GearItem => ({
    id: `preview-${isDuplicate ? 'duplicate' : 'new'}-${index}`,
    user_id: '',
    item_type: item.item_type,
    description: item.description,
    brand: item.brand || null,
    model: item.model || null,
    consumable: item.consumable,
    price: item.price || null,
    weight_g: item.weight_g,
    weight_unit_display: item.weight_unit_display,
    notes: item.notes || null,
    image_url: item.image_url || null,
    url: item.url || null,
    created_at: '',
    updated_at: ''
  })

  // Combine new items and duplicates for display
  const allItemsForTable: GearItem[] = [
    ...newItems.map((item, index) => convertToGearItem(item, index, false)),
    ...duplicates.map((item, index) => convertToGearItem(item, index, true))
  ]

  // Function to check if an item is a duplicate
  const isDuplicateItem = (item: GearItem): boolean => {
    return item.id.startsWith('preview-duplicate-')
  }

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="flex items-center gap-2 text-lg">
          <CheckCircle className="h-4 w-4 text-green-600" />
          Import Preview
          {metadata?.listName && (
            <span className="text-sm font-normal text-muted-foreground">• {metadata.listName}</span>
          )}
        </CardTitle>
        <CardDescription className="text-sm">
          {newItems.length > 0 ? (
            <>
              {newItems.length} new items ready to import
              {duplicates.length > 0 && (
                <span className="text-muted-foreground"> • {duplicates.length} duplicates skipped</span>
              )}
            </>
          ) : (
            "No new items to import (all items already exist)"
          )}
        </CardDescription>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* No New Items Special Case */}
        {newItems.length === 0 && duplicates.length > 0 && (
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">All items already exist in your gear library</div>
              <div className="text-sm">
                We found {duplicates.length} items from your import, but they all match items you already have.
                You can go back to import different data or close this dialog.
              </div>
            </AlertDescription>
          </Alert>
        )}

        {/* Errors */}
        {errors.length > 0 && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Errors:</div>
              <ul className="list-disc list-inside space-y-1">
                {errors.map((error, i) => (
                  <li key={i} className="text-sm">{error}</li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        {/* Summary Stats - Compact */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-2">
          <StatTile
            title="New Items"
            value={newItems.length}
            description="items to import"
            icon={Package}
            iconColor="success"
            compact={true}
          />
          <StatTile
            title="Duplicates"
            value={duplicates.length}
            description="skipped"
            icon={X}
            iconColor="warning"
            compact={true}
          />
          <StatTile
            title="New Weight"
            value={formatWeightForDisplay(newItemsWeight)}
            description="total weight"
            icon={Weight}
            iconColor="info"
            compact={true}
          />
          <StatTile
            title="Categories"
            value={newCategories.size}
            description="gear types"
            icon={Tag}
            iconColor="primary"
            compact={true}
          />
        </div>

        {/* All Items Table (New + Duplicates) */}
        {allItemsForTable.length > 0 && (
          <div className="space-y-2">
            <div className="max-h-48 overflow-y-auto">
              <GearTable
                items={allItemsForTable}
                viewMode="compact"
                weightUnit="g" // Show in grams for now (could be made configurable)
                onEdit={() => {}} // No editing in preview
                onDelete={() => {}} // No deleting in preview
                showActions={false}
                isDuplicate={isDuplicateItem}
              />
            </div>
          </div>
        )}


        {/* Import Error */}
        {importError && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Failed:</div>
              <div className="text-sm">{importError}</div>
            </AlertDescription>
          </Alert>
        )}

        {/* Actions */}
        <div className="flex justify-center gap-2 pt-2">
          {newItems.length > 0 ? (
            <>
              <Button onClick={handleImport} disabled={isImporting} size="sm">
                {isImporting ? (
                  <>
                    <Loader2 className="h-3 w-3 mr-1 animate-spin" />
                    Importing...
                  </>
                ) : (
                  `Import ${newItems.length} Items`
                )}
              </Button>
              <Button variant="outline" onClick={onCancel} disabled={isImporting} size="sm">
                Back
              </Button>
            </>
          ) : (
            <Button variant="outline" onClick={onCancel} size="sm">
              Back to Import
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

import { supabase } from './supabase'
import type { List } from '@/types/database'
import type { Repository } from './persistence'

class ListRepository implements Repository<List> {
  private readonly userId: string

  constructor(userId: string) {
    this.userId = userId
  }

  async create(item: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>): Promise<List> {
    const { data, error } = await supabase
      .from('lists')
      .insert({ ...item, user_id: this.userId })
      .select()
      .single()

    if (error) throw error
    return data
  }

  async read(id: string): Promise<List | null> {
    const { data, error } = await supabase
      .from('lists')
      .select('*')
      .eq('id', id)
      .eq('user_id', this.userId)
      .single()

    if (error && error.code !== 'PGRST116') throw error
    return data
  }

  async update(id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>): Promise<List> {
    const { data, error } = await supabase
      .from('lists')
      .update(updates)
      .eq('id', id)
      .eq('user_id', this.userId)
      .select()
      .single()

    if (error) throw error
    return data
  }

  async delete(id: string): Promise<void> {
    const { error } = await supabase
      .from('lists')
      .delete()
      .eq('id', id)
      .eq('user_id', this.userId)

    if (error) throw error
  }

  async list(): Promise<List[]> {
    const { data, error } = await supabase
      .from('lists')
      .select('*')
      .eq('user_id', this.userId)
      .order('name')

    if (error) throw error
    return data || []
  }

  async count(): Promise<number> {
    const { count, error } = await supabase
      .from('lists')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', this.userId)

    if (error) throw error
    return count || 0
  }

  // List-specific methods
  async addGearToList(listId: string, gearId: string): Promise<List> {
    // First get the current list
    const list = await this.read(listId)
    if (!list) throw new Error('List not found')

    // Add gear ID to the array if not already present
    const updatedGearIds = list.gear_ids.includes(gearId) 
      ? list.gear_ids 
      : [...list.gear_ids, gearId]

    return this.update(listId, { gear_ids: updatedGearIds })
  }

  async removeGearFromList(listId: string, gearId: string): Promise<List> {
    // First get the current list
    const list = await this.read(listId)
    if (!list) throw new Error('List not found')

    // Remove gear ID from the array
    const updatedGearIds = list.gear_ids.filter(id => id !== gearId)

    return this.update(listId, { gear_ids: updatedGearIds })
  }

  async addMultipleGearToList(listId: string, gearIds: string[]): Promise<List> {
    // First get the current list
    const list = await this.read(listId)
    if (!list) throw new Error('List not found')

    // Add gear IDs to the array, avoiding duplicates
    const existingIds = new Set(list.gear_ids)
    const newIds = gearIds.filter(id => !existingIds.has(id))
    const updatedGearIds = [...list.gear_ids, ...newIds]

    return this.update(listId, { gear_ids: updatedGearIds })
  }

  async duplicateList(listId: string, newName: string): Promise<List> {
    // Get the original list
    const originalList = await this.read(listId)
    if (!originalList) throw new Error('List not found')

    // Create a new list with the same gear IDs but new name
    return this.create({
      name: newName,
      gear_ids: [...originalList.gear_ids] // Create a copy of the array
    })
  }
}

export const createListRepository = (userId: string) => new ListRepository(userId)

import { supabase } from './supabase'
import { createGearRepository } from './gearRepository'
import { createListRepository } from './listRepository'
import type { 
  ListParseResult, 
  ParsedList, 
  ParsedListCategory, 
  ParsedListedGearItem 
} from '@/utils/parser'
import type { 
  List, 
  ListCategory, 
  ListedGearItem, 
  GearItem 
} from '@/types/database'

interface ImportResult {
  success: boolean
  list?: List
  errors: string[]
  warnings: string[]
  metadata?: {
    gearItemsCreated: number
    gearItemsReused: number
    categoriesCreated: number
    listedGearItemsCreated: number
  }
}

class ImportService {
  private readonly userId: string

  constructor(userId: string) {
    this.userId = userId
  }

  /**
   * Import a complete list structure in a single database transaction
   * This ensures atomicity - either everything is created or nothing is created
   */
  async importList(parseResult: ListParseResult): Promise<ImportResult> {
    const result: ImportResult = {
      success: false,
      errors: [],
      warnings: [],
      metadata: {
        gearItemsCreated: 0,
        categoriesCreated: 0,
        listedGearItemsCreated: 0
      }
    }

    // Early validation
    if (!parseResult.success || parseResult.errors.length > 0) {
      result.errors.push(...parseResult.errors)
      return result
    }

    if (parseResult.listedGearItems.length === 0) {
      result.errors.push('No items to import')
      return result
    }

    try {
      // Check for duplicate list name and adjust if necessary
      const finalListName = await this.getUniqueListName(parseResult.list.name)
      if (finalListName !== parseResult.list.name) {
        result.warnings.push(`List name changed from "${parseResult.list.name}" to "${finalListName}" to avoid duplicates`)
      }

      // Execute the entire import in a single transaction
      const importedList = await this.executeTransactionalImport({
        ...parseResult,
        list: { ...parseResult.list, name: finalListName }
      })

      result.success = true
      result.list = importedList.list
      result.metadata = importedList.metadata
      result.warnings.push(...parseResult.warnings)

      // Add helpful import summary
      if (importedList.metadata.gearItemsReused > 0) {
        result.warnings.push(`Reused ${importedList.metadata.gearItemsReused} existing gear items from your library`)
      }
      if (importedList.metadata.gearItemsCreated > 0) {
        result.warnings.push(`Created ${importedList.metadata.gearItemsCreated} new gear items`)
      }

    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown import error'
      result.errors.push(`Import failed: ${message}`)
    }

    return result
  }

  /**
   * Get a unique list name by appending (duplicate) suffix if needed
   */
  private async getUniqueListName(proposedName: string): Promise<string> {
    const listRepository = createListRepository(this.userId)
    const existingLists = await listRepository.list()
    const existingNames = new Set(existingLists.map(list => list.name.toLowerCase()))

    let finalName = proposedName
    let counter = 0

    while (existingNames.has(finalName.toLowerCase())) {
      counter++
      finalName = counter === 1 
        ? `${proposedName} (duplicate)`
        : `${proposedName} (duplicate ${counter})`
    }

    return finalName
  }

  /**
   * Execute the complete import in a single database transaction
   */
  private async executeTransactionalImport(parseResult: ListParseResult): Promise<{
    list: List
    metadata: {
      gearItemsCreated: number
      categoriesCreated: number  
      listedGearItemsCreated: number
    }
  }> {
    // Use Supabase transaction to ensure atomicity
    const { data, error } = await supabase.rpc('import_complete_list', {
      user_id: this.userId,
      list_data: parseResult.list,
      categories_data: parseResult.categories,
      listed_gear_items_data: parseResult.listedGearItems
    })

    if (error) {
      // If RPC doesn't exist, fall back to manual transaction
      if (error.message.includes('function import_complete_list')) {
        return this.executeManualTransaction(parseResult)
      }
      throw error
    }

    return data
  }

  /**
   * Manual transaction implementation as fallback
   * This creates all records step by step within a transaction
   * For list imports, we reuse existing gear items but always create new list structure
   */
  private async executeManualTransaction(parseResult: ListParseResult): Promise<{
    list: List
    metadata: {
      gearItemsCreated: number
      gearItemsReused: number
      categoriesCreated: number
      listedGearItemsCreated: number
    }
  }> {
    const metadata = {
      gearItemsCreated: 0,
      gearItemsReused: 0,
      categoriesCreated: 0,
      listedGearItemsCreated: 0
    }

    // Start transaction
    const { data: txData, error: txError } = await supabase.rpc('begin_transaction')
    if (txError) throw txError

    try {
      // 1. Create the list
      const { data: listData, error: listError } = await supabase
        .from('lists')
        .insert({
          name: parseResult.list.name,
          user_id: this.userId,
          gear_ids: [] // Will be populated after creating listed items
        })
        .select()
        .single()

      if (listError) throw listError
      const createdList: List = listData

      // 2. Create all categories
      const categoryInserts = parseResult.categories.map(category => ({
        list_id: createdList.id,
        name: category.name,
        sort_index: category.sort_index,
        icon: category.icon,
        color: category.color
      }))

      const { data: categoriesData, error: categoriesError } = await supabase
        .from('list_categories')
        .insert(categoryInserts)
        .select()

      if (categoriesError) throw categoriesError
      const createdCategories: ListCategory[] = categoriesData
      metadata.categoriesCreated = createdCategories.length

      // Create category name to ID mapping
      const categoryMap = new Map<string, string>()
      createdCategories.forEach(cat => categoryMap.set(cat.name, cat.id))

      // 3. Handle gear items - check for existing items first, create new ones only if needed
      // Get existing gear items for this user
      const { data: existingGear, error: existingGearError } = await supabase
        .from('gear_items')
        .select('*')
        .eq('user_id', this.userId)

      if (existingGearError) throw existingGearError

      // Create a map of existing gear items by description + weight
      const existingGearMap = new Map<string, GearItem>()
      existingGear.forEach(gear => {
        const key = `${gear.description.toLowerCase().trim()}-${gear.weight_g}`
        existingGearMap.set(key, gear)
      })

      // Identify which gear items need to be created vs reused
      const gearToCreate: typeof parseResult.listedGearItems[0]['gearItem'][] = []
      const gearMap = new Map<string, string>() // key -> gear_id mapping

      // First pass: identify unique gear items and check for existing ones
      const uniqueGearItems = new Map<string, ParsedListedGearItem>()
      parseResult.listedGearItems.forEach(item => {
        const key = `${item.gearItem.description.toLowerCase().trim()}-${item.gearItem.weight_g}`
        if (!uniqueGearItems.has(key)) {
          uniqueGearItems.set(key, item)
        }
      })

      // Second pass: determine what needs to be created
      uniqueGearItems.forEach((item, key) => {
        const existingItem = existingGearMap.get(key)
        if (existingItem) {
          // Reuse existing item
          gearMap.set(key, existingItem.id)
          metadata.gearItemsReused++
        } else {
          // Need to create new item
          gearToCreate.push(item.gearItem)
        }
      })

      // Create new gear items if needed
      if (gearToCreate.length > 0) {
        const gearInserts = gearToCreate.map(item => ({
          user_id: this.userId,
          description: item.description,
          item_type: item.item_type,
          brand: item.brand,
          model: item.model,
          weight_g: item.weight_g,
          weight_unit_display: item.weight_unit_display,
          consumable: item.consumable,
          price: item.price,
          notes: item.notes,
          image_url: item.image_url,
          url: item.url
        }))

        const { data: gearData, error: gearError } = await supabase
          .from('gear_items')
          .insert(gearInserts)
          .select()

        if (gearError) throw gearError
        const createdGear: GearItem[] = gearData
        metadata.gearItemsCreated = createdGear.length

        // Add newly created gear to the mapping
        createdGear.forEach(gear => {
          const key = `${gear.description.toLowerCase().trim()}-${gear.weight_g}`
          gearMap.set(key, gear.id)
        })
      }

      // 4. Create listed gear items
      const listedItemInserts = parseResult.listedGearItems.map(item => {
        const gearKey = `${item.gearItem.description.toLowerCase().trim()}-${item.gearItem.weight_g}`
        const gearId = gearMap.get(gearKey)
        const categoryId = categoryMap.get(item.categoryName)

        if (!gearId || !categoryId) {
          throw new Error(`Failed to map gear item or category: ${item.gearItem.description}`)
        }

        return {
          gear_id: gearId,
          list_category_id: categoryId,
          quantity: item.quantity,
          worn: item.worn,
          weight_g_override: item.weight_g_override,
          notes: item.notes,
          sort_index: item.sort_index
        }
      })

      const { data: listedItemsData, error: listedItemsError } = await supabase
        .from('listed_gear_items')
        .insert(listedItemInserts)
        .select()

      if (listedItemsError) throw listedItemsError
      metadata.listedGearItemsCreated = listedItemsData.length

      // 5. Update list with gear_ids (for legacy compatibility)
      const allGearIds = Array.from(gearMap.values())
      const { error: updateError } = await supabase
        .from('lists')
        .update({ gear_ids: allGearIds })
        .eq('id', createdList.id)

      if (updateError) throw updateError

      // Commit transaction
      const { error: commitError } = await supabase.rpc('commit_transaction')
      if (commitError) throw commitError

      return {
        list: { ...createdList, gear_ids: allGearIds },
        metadata
      }

    } catch (error) {
      // Rollback transaction
      await supabase.rpc('rollback_transaction')
      throw error
    }
  }
}

