export function ImportGearForm({ onCancel, className }: ImportGearFormProps) {
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('url')
  const [existingItems, setExistingItems] = useState<GearItem[]>([])
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    items: [],
    newItems: [],
    duplicates: [],
    errors: [],
    warnings: []
  })

  // Fetch existing gear items on mount
  useEffect(() => {
    const fetchExistingItems = async () => {
      if (!user) return

      try {
        const gearRepository = createGearRepository(user.id)
        const items = await gearRepository.list()
        setExistingItems(items)
      } catch (error) {
        console.error('Failed to fetch existing gear items:', error)
      }
    }

    fetchExistingItems()
  }, [user])

  // Function to check if two items are duplicates
  const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
    // Match on item_type and description (case insensitive)
    const importItemType = importItem.item_type.toLowerCase().trim()
    const importDescription = (importItem.description || '').toLowerCase().trim()
    const existingItemType = existingItem.item_type.toLowerCase().trim()
    const existingDescription = (existingItem.description || '').toLowerCase().trim()

    return importItemType === existingItemType && importDescription === existingDescription
  }

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    // Deduplicate against existing items
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    data.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Add deduplication warnings (summary only, no ugly lists)
    const updatedWarnings = [...warnings]
    if (duplicates.length > 0) {
      updatedWarnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      updatedWarnings.push(`${newItems.length} new items ready to import`)
    }

    setImportState({
      step: 'preview', // Always show preview, even if no new items
      items: data,
      newItems,
      duplicates,
      errors,
      warnings: updatedWarnings,
      metadata
    })
  }


  const handleReset = () => {
    setImportState({
      step: 'input',
      items: [],
      newItems: [],
      duplicates: [],
      errors: [],
      warnings: [],
      metadata: undefined
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <ImportPreview
        newItems={importState.newItems}
        duplicates={importState.duplicates}
        errors={importState.errors}
        warnings={importState.warnings}
        metadata={importState.metadata}
        onCancel={handleReset}
        className={className}
      />
    )
  }


  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Import Gear</CardTitle>
        <CardDescription className="text-sm">
          Import your gear from LighterPack by URL or CSV file
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="url" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
          </TabsList>

          <TabsContent value="url" className="mt-4">
            <UrlImport onImportData={handleImportData} />
          </TabsContent>

          <TabsContent value="csv" className="mt-4">
            <CsvImport onImportData={handleImportData} />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-4 pt-3 border-t">
          <Button variant="ghost" onClick={handleClose} size="sm">
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

-- Create list_categories table
CREATE TABLE list_categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    list_id UUID NOT NULL REFERENCES lists(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    sort_index INTEGER NOT NULL DEFAULT 0,
    icon TEXT,
    color TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),

    -- Unique constraint to avoid duplicate names per list (or allow if you prefer)
    CONSTRAINT unique_list_category_name UNIQUE (list_id, name)
);

-- Enable RLS
ALTER TABLE list_categories ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for list_categories
-- Users can only access categories for lists they own
CREATE POLICY "Users can view their own list categories" ON list_categories
    FOR SELECT USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can insert categories for their own lists" ON list_categories
    FOR INSERT WITH CHECK (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can update their own list categories" ON list_categories
    FOR UPDATE USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can delete their own list categories" ON list_categories
    FOR DELETE USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

-- Create index for performance
CREATE INDEX idx_list_categories_list_id ON list_categories(list_id);
CREATE INDEX idx_list_categories_sort_index ON list_categories(list_id, sort_index);

-- Create updated_at trigger
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_list_categories_updated_at 
    BEFORE UPDATE ON list_categories 
    FOR EACH ROW 
    EXECUTE FUNCTION update_updated_at_column();

-- Create listed_gear_items table (junction table for gear items in lists with metadata)
CREATE TABLE listed_gear_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gear_id UUID NOT NULL REFERENCES gear_items(id) ON DELETE RESTRICT,
    list_category_id UUID REFERENCES list_categories(id) ON DELETE SET NULL,
    quantity INTEGER NOT NULL DEFAULT 1,
    worn BOOLEAN NOT NULL DEFAULT false,
    weight_g_override INTEGER, -- nullable, allows override of gear item weight
    notes TEXT, -- nullable
    sort_index INTEGER, -- nullable, for custom ordering within category
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE listed_gear_items ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for listed_gear_item
-- Users can only access listed gear items for gear they own
CREATE POLICY "Users can view their own listed gear items" ON listed_gear_items
    FOR SELECT USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can insert listed gear items for their own gear" ON listed_gear_items
    FOR INSERT WITH CHECK (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
        AND (
            list_category_id IS NULL OR
            list_category_id IN (
                SELECT lc.id FROM list_categories lc
                JOIN lists l ON l.id = lc.list_id
                WHERE l.user_id = auth.uid()
            )
        )
    );

CREATE POLICY "Users can update their own listed gear items" ON listed_gear_items
    FOR UPDATE USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can delete their own listed gear items" ON listed_gear_items
    FOR DELETE USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

-- Create indexes for performance
CREATE INDEX idx_listed_gear_item_gear_id ON listed_gear_items(gear_id);
CREATE INDEX idx_listed_gear_item_category_id ON listed_gear_items(list_category_id);
CREATE INDEX idx_listed_gear_item_category_sort ON listed_gear_items(list_category_id, sort_index);

-- Create updated_at trigger (created_at has DEFAULT NOW() so no trigger needed)
CREATE TRIGGER update_listed_gear_items_updated_at
    BEFORE UPDATE ON listed_gear_items
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

