-- RPC function for transactional operations support
-- These functions help manage transactions in Supabase

-- Begin transaction function
CREATE OR REPLACE FUNCTION begin_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically handles transactions within functions
    -- This is a placeholder for consistency with the ImportService
    NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Commit transaction function
CREATE OR REPLACE FUNCTION commit_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically commits at the end of functions
    -- This is a placeholder for consistency with the ImportService
    NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Rollback transaction function
CREATE OR REPLACE FUNCTION rollback_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically rolls back on errors
    -- This is a placeholder for consistency with the ImportService
    RAISE EXCEPTION 'Transaction rollback requested';
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Main import function for complete list structures
CREATE OR REPLACE FUNCTION import_complete_list(
    p_user_id UUID,
    p_list_data JSONB,
    p_categories_data JSONB,
    p_listed_gear_items_data JSONB
)
RETURNS JSONB AS $$
DECLARE
    v_list_id UUID;
    v_category JSONB;
    v_category_id UUID;
    v_category_map JSONB := '{}'::JSONB;
    v_gear_item JSONB;
    v_gear_id UUID;
    v_gear_map JSONB := '{}'::JSONB;
    v_listed_item JSONB;
    v_existing_gear RECORD;
    v_metadata JSONB;
    v_gear_items_created INT := 0;
    v_gear_items_reused INT := 0;
    v_categories_created INT := 0;
    v_listed_items_created INT := 0;
    v_all_gear_ids UUID[] := '{}';
BEGIN
    -- Create the list
    INSERT INTO lists (name, user_id, gear_ids)
    VALUES (
        p_list_data->>'name',
        p_user_id,
        ARRAY[]::UUID[]
    )
    RETURNING id INTO v_list_id;

    -- Create categories and build mapping
    FOR v_category IN SELECT * FROM jsonb_array_elements(p_categories_data)
    LOOP
        INSERT INTO list_categories (
            list_id,
            name,
            sort_index,
            icon,
            color
        )
        VALUES (
            v_list_id,
            v_category->>'name',
            (v_category->>'sort_index')::INTEGER,
            v_category->>'icon',
            v_category->>'color'
        )
        RETURNING id INTO v_category_id;

        v_category_map := jsonb_set(v_category_map, ARRAY[v_category->>'name'], to_jsonb(v_category_id));
        v_categories_created := v_categories_created + 1;
    END LOOP;

    -- Process gear items and create listed gear items
    FOR v_listed_item IN SELECT * FROM jsonb_array_elements(p_listed_gear_items_data)
    LOOP
        v_gear_item := v_listed_item->'gearItem';

        -- Check if gear item already exists for this user
        SELECT id INTO v_existing_gear
        FROM gear_items
        WHERE user_id = p_user_id
            AND LOWER(TRIM(description)) = LOWER(TRIM(v_gear_item->>'description'))
            AND ABS(weight_g - (v_gear_item->>'weight_g')::INTEGER) <= 5
        LIMIT 1;

        IF FOUND THEN
            -- Reuse existing gear item
            v_gear_id := v_existing_gear.id;
            v_gear_items_reused := v_gear_items_reused + 1;
        ELSE
            -- Create new gear item
            INSERT INTO gear_items (
                user_id,
                description,
                item_type,
                brand,
                model,
                weight_g,
                weight_unit_display,
                consumable,
                price,
                notes,
                image_url,
                url
            )
            VALUES (
                p_user_id,
                v_gear_item->>'description',
                v_gear_item->>'item_type',
                v_gear_item->>'brand',
                v_gear_item->>'model',
                (v_gear_item->>'weight_g')::INTEGER,
                v_gear_item->>'weight_unit_display',
                (v_gear_item->>'consumable')::BOOLEAN,
                (v_gear_item->>'price')::NUMERIC,
                v_gear_item->>'notes',
                v_gear_item->>'image_url',
                v_gear_item->>'url'
            )
            RETURNING id INTO v_gear_id;

            v_gear_items_created := v_gear_items_created + 1;
        END IF;

        -- Add gear_id to array for list
        v_all_gear_ids := array_append(v_all_gear_ids, v_gear_id);

        -- Create listed gear item
        INSERT INTO listed_gear_items (
            gear_id,
