import { supabase } from './supabase'
import { createGearRepository } from './gearRepository'
import { createListRepository } from './listRepository'
import type { 
  ListParseResult, 
  ParsedList, 
  ParsedListCategory, 
  ParsedListedGearItem 
} from '@/utils/parser'
import type { 
  List, 
  ListCategory, 
  ListedGearItem, 
  GearItem 
} from '@/types/database'

interface ImportResult {
  success: boolean
  list?: List
  errors: string[]
  warnings: string[]
  metadata?: {
    gearItemsCreated: number
    gearItemsReused: number
    categoriesCreated: number
    listedGearItemsCreated: number
  }
}

class ImportService {
  private readonly userId: string

  constructor(userId: string) {
    this.userId = userId
  }

  /**
   * Import a complete list structure in a single database transaction
   * This ensures atomicity - either everything is created or nothing is created
   */
  async importList(parseResult: ListParseResult): Promise<ImportResult> {
    const result: ImportResult = {
      success: false,
      errors: [],
      warnings: [],
      metadata: {
        gearItemsCreated: 0,
        categoriesCreated: 0,
        listedGearItemsCreated: 0
      }
    }

    // Early validation
    if (!parseResult.success || parseResult.errors.length > 0) {
      result.errors.push(...parseResult.errors)
      return result
    }

    if (parseResult.listedGearItems.length === 0) {
      result.errors.push('No items to import')
      return result
    }

    try {
      // Check for duplicate list name and adjust if necessary
      const finalListName = await this.getUniqueListName(parseResult.list.name)
      if (finalListName !== parseResult.list.name) {
        result.warnings.push(`List name changed from "${parseResult.list.name}" to "${finalListName}" to avoid duplicates`)
      }

      // Execute the entire import in a single transaction
      const importedList = await this.executeTransactionalImport({
        ...parseResult,
        list: { ...parseResult.list, name: finalListName }
      })

      result.success = true
      result.list = importedList.list
      result.metadata = importedList.metadata
      result.warnings.push(...parseResult.warnings)

      // Add helpful import summary
      if (importedList.metadata.gearItemsReused > 0) {
        result.warnings.push(`Reused ${importedList.metadata.gearItemsReused} existing gear items from your library`)
      }
      if (importedList.metadata.gearItemsCreated > 0) {
        result.warnings.push(`Created ${importedList.metadata.gearItemsCreated} new gear items`)
      }

    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown import error'
      result.errors.push(`Import failed: ${message}`)
    }

    return result
  }

  /**
   * Get a unique list name by appending (duplicate) suffix if needed
   */
  private async getUniqueListName(proposedName: string): Promise<string> {
    const listRepository = createListRepository(this.userId)
    const existingLists = await listRepository.list()
    const existingNames = new Set(existingLists.map(list => list.name.toLowerCase()))

    let finalName = proposedName
    let counter = 0

    while (existingNames.has(finalName.toLowerCase())) {
      counter++
      finalName = counter === 1 
        ? `${proposedName} (duplicate)`
        : `${proposedName} (duplicate ${counter})`
    }

    return finalName
  }

  /**
   * Execute the complete import in a single database transaction
   */
  private async executeTransactionalImport(parseResult: ListParseResult): Promise<{
    list: List
    metadata: {
      gearItemsCreated: number
      categoriesCreated: number  
      listedGearItemsCreated: number
    }
  }> {
    // Use Supabase transaction to ensure atomicity
    const { data, error } = await supabase.rpc('import_complete_list', {
      p_user_id: this.userId,
      p_list_data: parseResult.list,
      p_categories_data: parseResult.categories,
      p_listed_gear_items_data: parseResult.listedGearItems
    })

    if (error) {
      // If RPC doesn't exist, fall back to manual transaction
      if (error.message.includes('function import_complete_list')) {
        return this.executeManualTransaction(parseResult)
      }
      throw error
    }

    return data
  }

  /**
   * Manual transaction implementation as fallback
   * This creates all records step by step within a transaction
   * For list imports, we reuse existing gear items but always create new list structure
   */
  private async executeManualTransaction(parseResult: ListParseResult): Promise<{
    list: List
    metadata: {
      gearItemsCreated: number
      gearItemsReused: number
      categoriesCreated: number
      listedGearItemsCreated: number
    }
  }> {
    const metadata = {
      gearItemsCreated: 0,
      gearItemsReused: 0,
      categoriesCreated: 0,
      listedGearItemsCreated: 0
    }

    // Start transaction - check if RPC exists first
    const { error: txError } = await supabase.rpc('begin_transaction')
    if (txError && !txError.message.includes('function begin_transaction')) {
      throw txError
    }

    try {
      // 1. Create the list
      const { data: listData, error: listError } = await supabase
        .from('lists')
        .insert({
          name: parseResult.list.name,
          user_id: this.userId,
          gear_ids: [] // Will be populated after creating listed items
        })
        .select()
        .single()

      if (listError) throw listError
      const createdList: List = listData

      // 2. Create all categories
      const categoryInserts = parseResult.categories.map(category => ({
        list_id: createdList.id,
        name: category.name,
        sort_index: category.sort_index,
        icon: category.icon,
        color: category.color
      }))

      const { data: categoriesData, error: categoriesError } = await supabase
        .from('list_categories')
        .insert(categoryInserts)
        .select()

      if (categoriesError) throw categoriesError
      const createdCategories: ListCategory[] = categoriesData
      metadata.categoriesCreated = createdCategories.length

      // Create category name to ID mapping
      const categoryMap = new Map<string, string>()
      createdCategories.forEach(cat => categoryMap.set(cat.name, cat.id))

      // 3. Handle gear items - check for existing items first, create new ones only if needed
      // Get existing gear items for this user
      const { data: existingGear, error: existingGearError } = await supabase
        .from('gear_items')
        .select('*')
        .eq('user_id', this.userId)

      if (existingGearError) throw existingGearError

      // Create a map of existing gear items by description + weight
      const existingGearMap = new Map<string, GearItem>()
      existingGear.forEach(gear => {
        const key = `${gear.description.toLowerCase().trim()}-${gear.weight_g}`
        existingGearMap.set(key, gear)
      })

      // Identify which gear items need to be created vs reused
      const gearToCreate: typeof parseResult.listedGearItems[0]['gearItem'][] = []
      const gearMap = new Map<string, string>() // key -> gear_id mapping

      // First pass: identify unique gear items and check for existing ones
      const uniqueGearItems = new Map<string, ParsedListedGearItem>()
      parseResult.listedGearItems.forEach(item => {
        const key = `${item.gearItem.description.toLowerCase().trim()}-${item.gearItem.weight_g}`
        if (!uniqueGearItems.has(key)) {
          uniqueGearItems.set(key, item)
        }
      })

      // Second pass: determine what needs to be created
      uniqueGearItems.forEach((item, key) => {
        const existingItem = existingGearMap.get(key)
        if (existingItem) {
          // Reuse existing item
          gearMap.set(key, existingItem.id)
          metadata.gearItemsReused++
        } else {
          // Need to create new item
          gearToCreate.push(item.gearItem)
        }
      })

      // Create new gear items if needed
      if (gearToCreate.length > 0) {
        const gearInserts = gearToCreate.map(item => ({
          user_id: this.userId,
          description: item.description,
          item_type: item.item_type,
          brand: item.brand,
          model: item.model,
          weight_g: item.weight_g,
          weight_unit_display: item.weight_unit_display,
          consumable: item.consumable,
          price: item.price,
          notes: item.notes,
          image_url: item.image_url,
          url: item.url
        }))

        const { data: gearData, error: gearError } = await supabase
          .from('gear_items')
          .insert(gearInserts)
          .select()

        if (gearError) throw gearError
        const createdGear: GearItem[] = gearData
        metadata.gearItemsCreated = createdGear.length

        // Add newly created gear to the mapping
        createdGear.forEach(gear => {
          const key = `${gear.description.toLowerCase().trim()}-${gear.weight_g}`
          gearMap.set(key, gear.id)
        })
      }

      // 4. Create listed gear items
      const listedItemInserts = parseResult.listedGearItems.map(item => {
        const gearKey = `${item.gearItem.description.toLowerCase().trim()}-${item.gearItem.weight_g}`
        const gearId = gearMap.get(gearKey)
        const categoryId = categoryMap.get(item.categoryName)

        if (!gearId || !categoryId) {
          throw new Error(`Failed to map gear item or category: ${item.gearItem.description}`)
        }

        return {
          gear_id: gearId,
          list_category_id: categoryId,
          quantity: item.quantity,
          worn: item.worn,
          weight_g_override: item.weight_g_override,
          notes: item.notes,
          sort_index: item.sort_index
        }
      })

      const { data: listedItemsData, error: listedItemsError } = await supabase
        .from('listed_gear_items')
        .insert(listedItemInserts)
        .select()

      if (listedItemsError) throw listedItemsError
      metadata.listedGearItemsCreated = listedItemsData.length

      // 5. Update list with gear_ids (for legacy compatibility)
      const allGearIds = Array.from(gearMap.values())
      const { error: updateError } = await supabase
        .from('lists')
        .update({ gear_ids: allGearIds })
        .eq('id', createdList.id)

      if (updateError) throw updateError

      // Commit transaction - check if RPC exists first
      const { error: commitError } = await supabase.rpc('commit_transaction')
      if (commitError && !commitError.message.includes('function commit_transaction')) {
        throw commitError
      }

      return {
        list: { ...createdList, gear_ids: allGearIds },
        metadata
      }

    } catch (error) {
      // Rollback transaction - check if RPC exists first
      const { error: rollbackError } = await supabase.rpc('rollback_transaction')
      if (rollbackError && !rollbackError.message.includes('function rollback_transaction')) {
        console.error('Rollback error:', rollbackError)
      }
      throw error
    }
  }
}

